/bin/bash -lc "grep -A1 '"'^@READ_126671$'"' nonhuman.fq; python -c 'import xml.etree.ElementTree as E
r=E.parse(\"blast200.xml\").getroot()
for it in r.findall(\".//Iteration\"):
 if it.findtext(\"Iteration_query-def\")==\"READ_126671\":
  for hit in it.findall(\"./Iteration_hits/Hit\")[:10]:
   h=hit.find(\"./Hit_hsps/Hsp\"); print(hit.findtext(\"Hit_def\"),h.findtext(\"Hsp_identity\"),h.findtext(\"Hsp_align-len\"),h.findtext(\"Hsp_query-from\"),h.findtext(\"Hsp_query-to\"),h.findtext(\"Hsp_hit-from\"),h.findtext(\"Hsp_hit-to\"),sep=\"\\t\")' "
